using System.IO.Compression;
using System.Text;

namespace Shapi.Infraestructura.Siembra.Demo;

/// <summary>
/// Copias completas, comprimidas y normalizadas a LF, de las especificaciones de los orígenes de demostración.
/// Las pruebas comprueban que sigan siendo idénticas a los YAML fuente.
/// </summary>
internal static class EspecificacionesDemo
{
    internal static string Envios { get; } = Descomprimir(EnviosGzip);
    internal static string Agro { get; } = Descomprimir(AgroGzip);

    private const string EnviosGzip = "";

    private const string AgroGzip = "";

    private static string Descomprimir(string contenido)
    {
        using var entrada = new MemoryStream(Convert.FromBase64String(contenido));
        using var gzip = new GZipStream(entrada, CompressionMode.Decompress);
        using var lector = new StreamReader(gzip, Encoding.UTF8);
        return lector.ReadToEnd();
    }
}
